using System;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Web.Script.Serialization;
static class UsabilityTests {
 static void Check(bool pass,string text){if(!pass)throw new Exception(text);Console.WriteLine("PASS: "+text);}
 public static void Policies(){var now=new DateTime(2026,10,26,10,0,0,DateTimeKind.Utc);var policy=new RecoveryPolicy();policy.Start();Check(!policy.Schedule(now),"Recovery is not armed by an unsuccessful initial connection");policy.Observe("Connected");Check(policy.Schedule(now)&&!policy.Ready(now,true)&&policy.Ready(now.AddSeconds(5),true),"Loss recovery starts with a five-second delay");Check(!policy.Ready(now.AddSeconds(10),false),"Recovery waits for network availability");policy.Cancel();policy.Observe("Connected");Check(!policy.Schedule(now)&&!policy.Armed,"Manual disconnect cannot be undone by a late connection callback");policy.Start();policy.Observe("Connected");policy.RejectAuthentication();Check(!policy.Schedule(now),"Authentication failure blocks automatic retry");policy.Observe("Connected");Check(policy.Schedule(now),"Successful corrected login restores recovery eligibility");policy.Start();policy.Observe("Connected");for(int i=0;i<5;i++){Check(policy.Schedule(now),"Bounded retry can be scheduled");policy.BeginAttempt();now=now.AddMinutes(2);}Check(!policy.Schedule(now)&&policy.Attempts==5,"Automatic recovery stops after five failed attempts");
  var profile=new Profile{Kind="OpenVPN",Path="C:\\usability-test.ovpn",Name="Old name"};var reuse=new LoginReusePolicy();Check(reuse.CanUse(profile,true,true)&&!reuse.CanUse(profile,true,true),"Saved login is automatically reused only once per attempt");reuse=new LoginReusePolicy();reuse.Reject();Check(!reuse.CanUse(profile,true,true),"Rejected saved login falls back to a prompt");profile.RequiresOtp=true;Check(!new LoginReusePolicy().CanUse(profile,true,true),"OTP profiles cannot bypass the prompt");profile.RequiresOtp=false;profile.OneClickLogin=false;Check(!new LoginReusePolicy().CanUse(profile,true,true),"One-click login respects the profile option");
  var migrated=new JavaScriptSerializer().Deserialize<Profile>("{\"Name\":\"Legacy\",\"Kind\":\"OpenVPN\",\"Path\":\"C:\\\\old.ovpn\"}");Check(migrated.AutoReconnect&&migrated.OneClickLogin&&!migrated.RequiresOtp,"Older profiles gain compatible recovery/login defaults");
 }
 public static void Window(MainWindow form){var flags=BindingFlags.NonPublic|BindingFlags.Instance;var profile=new Profile{Name="Office",Kind="OpenVPN",Path="C:\\edit-test.ovpn"};string key=CredentialStore.Key(profile);using(var editor=new ProfileEditor(profile)){editor.NameBox.Text="Renamed office";editor.GroupBox.Text="Work";editor.FavouriteBox.Checked=true;editor.ReconnectBox.Checked=false;editor.Apply(profile);}Check(profile.Name=="Renamed office"&&profile.Group=="Work"&&profile.Favourite&&!profile.AutoReconnect&&CredentialStore.Key(profile)==key,"Profile editing preserves the configuration and saved-login identity");
  var entries=MainWindow.FilterProfiles(new[]{new Profile{Name="Zed",Group="Work",Favourite=true},new Profile{Name="Alpha",Group="Personal"}},"");Check(entries[0].Name=="Zed"&&MainWindow.FilterProfiles(entries,"work").Count==1,"Favourites sort first and groups are searchable");string json=new JavaScriptSerializer().Serialize(profile);var restored=new JavaScriptSerializer().Deserialize<Profile>(json);Check(restored.Favourite&&restored.Group=="Work"&&!restored.AutoReconnect,"Profile edits persist through serialization");
  var testProfile=new Profile{Name="Saved test",Kind="OpenVPN",Path="C:\\saved-login-test-"+Guid.NewGuid().ToString("N")+".ovpn"};string target=CredentialStore.Key(testProfile);try{CredentialStore.Save(target,"fixture-user","fixture-pass");var fake=new VpnSession{Profile=testProfile};typeof(MainWindow).GetField("session",flags).SetValue(form,fake);typeof(MainWindow).GetField("loginReuse",flags).SetValue(form,new LoginReusePolicy());var result=(string[])typeof(MainWindow).GetMethod("Ask",flags).Invoke(form,new object[]{"VPN authentication: Auth",true});Check(result[0]=="fixture-user"&&result[1]=="fixture-pass","Saved login bypasses the dialog through the real credential callback");}finally{typeof(MainWindow).GetField("session",flags).SetValue(form,null);CredentialStore.Forget(target);}
 }
}
